    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "ClinicoPathPj",
                name = "pysurvival",
                version = c(0,1,0),
                options = options,
                results = pysurvivalResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Grouped Survival (Core, Python)
#'
#' 
#' @param data .
#' @param elapsedtime .
#' @param outcome .
#' @param explanatory .
#' @param subject .
#' @param outcomeLevel .
#' @param censorLevel .
#' @param timetypeoutput .
#' @param cutp .
#' @param ciWidth .
#' @param showSteps .
#' @param showCases .
#' @param showExplanations .
#' @param sc .
#' @param ci95 .
#' @param censored .
#' @param timefix .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mapping} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$missing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$logrank} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$logrankGroups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$covariance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$riskSets} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$medians} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$selectedTimes} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$steps} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$survivalPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pysurvival <- function(
    data,
    elapsedtime = NULL,
    outcome = NULL,
    explanatory = NULL,
    subject = NULL,
    outcomeLevel,
    censorLevel,
    timetypeoutput = "months",
    cutp = "12, 36, 60",
    ciWidth = 95,
    showSteps = FALSE,
    showCases = FALSE,
    showExplanations = FALSE,
    sc = FALSE,
    ci95 = FALSE,
    censored = FALSE,
    timefix = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pysurvival requires jmvcore to be installed (restart may be required)")

    if ( ! missing(elapsedtime)) elapsedtime <- jmvcore::resolveQuo(jmvcore::enquo(elapsedtime))
    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(explanatory)) explanatory <- jmvcore::resolveQuo(jmvcore::enquo(explanatory))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(elapsedtime), elapsedtime, NULL),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(explanatory), explanatory, NULL),
            `if`( ! missing(subject), subject, NULL))

    for (v in outcome) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in explanatory) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pysurvivalOptions$new(
        elapsedtime = elapsedtime,
        outcome = outcome,
        explanatory = explanatory,
        subject = subject,
        outcomeLevel = outcomeLevel,
        censorLevel = censorLevel,
        timetypeoutput = timetypeoutput,
        cutp = cutp,
        ciWidth = ciWidth,
        showSteps = showSteps,
        showCases = showCases,
        showExplanations = showExplanations,
        sc = sc,
        ci95 = ci95,
        censored = censored,
        timefix = timefix,
        showConsole = showConsole)

    analysis <- pysurvivalClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

